  --color-text-muted: #6e6e73;
  --color-accent:     #0071e3;
  --color-accent-hov: #0077ed;
  --color-danger:     #d93025;
  --color-danger-hov: #b71c1c;
  --color-danger-bg:  #fff5f5;
  --color-warning:    #c4500a;

  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  18px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10), 0 1px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 20px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.10);

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-text);
  background: var(--color-bg);
}

/* ─── Skip link ─────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-surface);
  color: var(--color-accent);
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: var(--shadow-md);
}
.skip-link:focus { top: 1rem; }

/* ─── Header ────────────────────────────────────────────────────── */
.site-header {
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.site-header__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: .75rem 1.5rem;
  display: flex;
  align-items: center;
  gap: .5rem;
}
.site-header__logo { font-size: 1.25rem; }
.site-header__name { font-size: 1.0625rem; font-weight: 700; letter-spacing: -.3px; }

/* ─── Main ──────────────────────────────────────────────────────── */
.main-content {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

/* ─── Breadcrumb ────────────────────────────────────────────────── */
.breadcrumb { margin-bottom: 1.5rem; }
.breadcrumb ol {
  list-style: none;
  display: flex;
  gap: .375rem;
  align-items: center;
  font-size: .875rem;
  color: var(--color-text-muted);
}
.breadcrumb li + li::before { content: "/"; color: var(--color-border); }
.breadcrumb a {
  color: var(--color-accent);
  text-decoration: none;
}
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ─── Image preview layout ──────────────────────────────────────── */
.image-preview {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  align-items: start;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
