.image-preview__figure {
  margin: 0;
  background: #0a0a0a;
  aspect-ratio: 4/3;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.image-preview__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.image-preview__caption { display: none; } /* visible in figcaption semantically; title is shown in meta */

.image-preview__meta {
  padding: 2rem 1.75rem 2rem 0;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.image-preview__title {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -.4px;
  color: var(--color-text);
}

/* ─── Meta list ─────────────────────────────────────────────────── */
.image-meta { border-top: 1px solid var(--color-border); padding-top: 1rem; }
.image-meta__row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: .45rem 0;
  font-size: .9375rem;
}
.image-meta__row + .image-meta__row {
  border-top: 1px solid var(--color-border);
}
.image-meta dt { color: var(--color-text-muted); }
.image-meta dd { font-weight: 500; }

/* ─── Action buttons ────────────────────────────────────────────── */
.image-preview__actions {
  display: flex;
  flex-direction: column;
  gap: .625rem;
  margin-top: auto;
  padding-top: 1rem;
  border-top: 1px solid var(--color-border);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .625rem 1rem;
  font-size: .9375rem;
  font-weight: 500;
  border: 1.5px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background .14s ease, border-color .14s ease, color .14s ease, box-shadow .14s ease;
  width: 100%;
  font-family: inherit;
  letter-spacing: -.1px;
}
.btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.btn--secondary {
  background: var(--color-bg);
  border-color: var(--color-border);
  color: var(--color-text);
}
.btn--secondary:hover {
  background: #eaeaed;
  border-color: #c7c7cc;
}

.btn--danger {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: #fff;
}
.btn--danger:hover {
  background: var(--color-danger-hov);
  border-color: var(--color-danger-hov);
}

/* ─── Dialog backdrop ───────────────────────────────────────────── */
dialog::backdrop {
  background: rgba(0, 0, 0, .45);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

