  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1rem;
}

.dialog__icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  color: var(--color-danger);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.dialog__title {
  font-size: 1.1875rem;
  font-weight: 700;
  letter-spacing: -.3px;
}

.dialog__body {
  font-size: .9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.dialog__actions {
  display: flex;
  gap: .75rem;
  width: 100%;
  margin-top: .5rem;
}
.dialog__actions .btn {
  flex: 1;
}

/* ─── Screen-reader-only utility ────────────────────────────────── */
.sr-only {
  position: absolute;
