(function () {
  'use strict';

  const dialog     = document.getElementById('delete-dialog');
  const trigger    = document.getElementById('delete-trigger');
  const cancelBtn  = document.getElementById('dialog-cancel');
  const confirmBtn = document.getElementById('dialog-confirm');
  const statusMsg  = document.getElementById('status-msg');

  // Open dialog; move initial focus to Cancel (not the destructive action).
  trigger.addEventListener('click', () => {
    dialog.showModal();
    cancelBtn.focus();
  });

  // Cancel — close without action.
  cancelBtn.addEventListener('click', () => {
    dialog.close('cancel');
  });

  // Confirm — close and announce deletion.
  confirmBtn.addEventListener('click', () => {
    dialog.close('delete');
  });

  // Handle the dialog's close event (covers Escape key, Cancel, and Confirm).
  dialog.addEventListener('close', () => {
    // Native <dialog> automatically returns focus to `trigger`.
    if (dialog.returnValue === 'delete') {
      // In a real app you would call your delete API here.
      statusMsg.textContent = 'Mountain Sunrise has been deleted from your library.';
      // Visually indicate the action (placeholder — a real app would navigate away or update the UI).
      trigger.disabled = true;
      trigger.textContent = 'Deleted';
    } else {
      statusMsg.textContent = 'Deletion cancelled.';
    }
  });
})();

