  } else {
    await route.continue().catch(() => route.abort());
  }
});

await page.setContent(html, { waitUntil: 'load' });
await page.addScriptTag({ path: '/tmp/axe.min.js' });

// Test 1: closed state
const r1 = await page.evaluate(async () => await window.axe.run());

// Test 2: open dialog state
await page.click('#delete-trigger');
await page.waitForSelector('#delete-dialog[open]');
const r2 = await page.evaluate(async () => await window.axe.run());

await browser.close();

function fmt(violations) {
  return violations.map(v => ({
    id: v.id,
    impact: v.impact,
    tags: v.tags.filter(t => t.startsWith('wcag') || t === 'best-practice'),
    targets: v.nodes.map(n => n.target),
    description: v.description,
    help: v.help,
  }));
}

const wcag1 = r1.violations.filter(v => !v.tags.includes('best-practice'));
const bp1   = r1.violations.filter(v =>  v.tags.includes('best-practice'));
const wcag2 = r2.violations.filter(v => !v.tags.includes('best-practice'));
const bp2   = r2.violations.filter(v =>  v.tags.includes('best-practice'));

console.log(JSON.stringify({
  closed: { wcag: fmt(wcag1), bp: fmt(bp1) },
  open:   { wcag: fmt(wcag2), bp: fmt(bp2) },
}, null, 2));

process.exit((wcag1.length + wcag2.length) > 0 ? 1 : 0);
