    <style>
/* ─── Reset & base ─────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:         #f5f5f7;
  --color-surface:    #ffffff;
  --color-border:     #e2e2e7;
  --color-text:       #1c1c1e;
  --color-text-muted: #6e6e73;
  --color-accent:     #0071e3;
  --color-danger:     #d93025;
  --color-danger-hov: #b71c1c;
  --color-danger-bg:  #fff5f5;

  --radius-sm:  6px;
  --radius-lg:  18px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10), 0 1px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 20px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.10);

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-text);
  background: var(--color-bg);
}

/* ─── Skip link ─────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-surface);
  color: var(--color-accent);
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: var(--shadow-md);
}
.skip-link:focus { top: 1rem; }

/* ─── Header ────────────────────────────────────────────────────── */
.site-header {
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.site-header__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: .75rem 1.5rem;
  display: flex;
  align-items: center;
  gap: .5rem;
}
.site-header__logo { font-size: 1.25rem; }
.site-header__name { font-size: 1.0625rem; font-weight: 700; letter-spacing: -.3px; }

/* ─── Main ──────────────────────────────────────────────────────── */
.main-content {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

/* ─── Breadcrumb ────────────────────────────────────────────────── */
.breadcrumb { margin-bottom: 1.5rem; }
.breadcrumb ol {
  list-style: none;
  display: flex;
  gap: .375rem;
  align-items: center;
  font-size: .875rem;
  color: var(--color-text-muted);
}
.breadcrumb li + li::before { content: "/"; color: var(--color-border); }
.breadcrumb a { color: var(--color-accent); text-decoration: none; }
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ─── Image preview layout ──────────────────────────────────────── */
.image-preview {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  align-items: start;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.image-preview__figure {
  margin: 0;
  background: #0a0a0a;
  aspect-ratio: 4/3;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.image-preview__img { width: 100%; height: 100%; object-fit: cover; display: block; }
.image-preview__caption { display: none; }
.image-preview__meta {
  padding: 2rem 1.75rem 2rem 0;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.image-preview__title {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -.4px;
  color: var(--color-text);
}

/* ─── Meta list ─────────────────────────────────────────────────── */
.image-meta { border-top: 1px solid var(--color-border); padding-top: 1rem; }
.image-meta__row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: .45rem 0;
  font-size: .9375rem;
}
.image-meta__row + .image-meta__row { border-top: 1px solid var(--color-border); }
.image-meta dt { color: var(--color-text-muted); }
.image-meta dd { font-weight: 500; }

/* ─── Action buttons ────────────────────────────────────────────── */
.image-preview__actions {
  display: flex;
  flex-direction: column;
  gap: .625rem;
  margin-top: auto;
  padding-top: 1rem;
  border-top: 1px solid var(--color-border);
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .625rem 1rem;
  font-size: .9375rem;
  font-weight: 500;
  border: 1.5px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background .14s ease, border-color .14s ease, color .14s ease;
  width: 100%;
  font-family: inherit;
  letter-spacing: -.1px;
}
.btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.btn--secondary {
  background: var(--color-bg);
  border-color: var(--color-border);
  color: var(--color-text);
}
.btn--secondary:hover { background: #eaeaed; border-color: #c7c7cc; }
.btn--danger {
  background: var(--color-danger);
  border-color: var(--color-danger);
  color: #fff;
}
.btn--danger:hover { background: var(--color-danger-hov); border-color: var(--color-danger-hov); }

/* ─── Dialog backdrop ───────────────────────────────────────────── */
dialog::backdrop {
  background: rgba(0,0,0,.45);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

/* ─── Dialog ────────────────────────────────────────────────────── */
dialog {
  border: none;
  border-radius: var(--radius-lg);
  padding: 0;
  width: min(440px, calc(100vw - 2rem));
  box-shadow: var(--shadow-lg);
  background: var(--color-surface);
  color: var(--color-text);
  margin: auto;
}
.dialog__inner {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1rem;
}
.dialog__icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  color: var(--color-danger);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.dialog__title { font-size: 1.1875rem; font-weight: 700; letter-spacing: -.3px; }
.dialog__body { font-size: .9375rem; color: var(--color-text-muted); line-height: 1.6; }
.dialog__actions { display: flex; gap: .75rem; width: 100%; margin-top: .5rem; }
.dialog__actions .btn { flex: 1; }

/* ─── Screen-reader-only utility ────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ─── Reduced motion ────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

/* ─── Forced colors (high-contrast mode) ───────────────────────── */
@media (forced-colors: active) {
  .btn { forced-color-adjust: auto; }
  dialog { border: 2px solid ButtonText; }
  .dialog__icon { border: 2px solid ButtonText; background: Canvas; color: ButtonText; }
}

/* ─── Responsive reflow ─────────────────────────────────────────── */
@media (max-width: 700px) {
  .image-preview { grid-template-columns: 1fr; }
  .image-preview__meta { padding: 0 1.25rem 1.5rem; }
  .image-preview__figure { aspect-ratio: 16/9; border-radius: var(--radius-lg) var(--radius-lg) 0 0; }
  .dialog__actions { flex-direction: column-reverse; }
}
